"""Archive listings."""
import subprocess

from vault.core.config import ARCHIVE_DIR


def list_archive(name: str) -> list[str]:
    import os
    # Ensure name is a simple filename and doesn't allow path traversal
    if os.path.basename(name) != name or not name:
        raise ValueError("Invalid name")

    # Use a list of arguments and shell=False to prevent command injection
    result = subprocess.run(["ls", f"{ARCHIVE_DIR}/{name}"], shell=False, capture_output=True, text=True, timeout=5)
    if result.returncode != 0:
        raise FileNotFoundError(name)
    return sorted(line for line in result.stdout.splitlines() if line)

